-- 0090_library_templates_49_100.sql (storefront templates, 2026-10-19)
--
-- Storefront template "Zay" v1, generated from
-- packages/store-sections/src/templates/zay/ by
-- `pnpm --filter @workspace/store-sections template:sql zay 0090_library_templates_49_100.sql`.
-- Insert-only: Adds the template row (never
-- the default; the store keeps its own until the seller uses it) and its
-- version, only when the key is new.
-- An existing template (and its current version) is never changed.
--
-- Idempotent.

WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'zay',
    '{"ar":"زي","en":"Zay"}'::jsonb,
    '{"ar":"أساسيات رجالي: كلمة كبيرة، رف الأسبوع، طقم أيام الشغل، خصم الكمية، المقارنة وآراء واتساب. أربع صفحات جاهزة.","en":"Men’s essentials: one big word, this week’s shelf, a weekday kit, quantity tiers, a comparison and WhatsApp reviews. Four ready pages."}'::jsonb,
    'fashion',
    500,
    false,
    true,
    false,
    ids.version_id
