-- 0090_library_templates_49_100.sql (storefront templates, 2026-10-19)
--
-- Storefront template "Sada" v1, generated from
-- packages/store-sections/src/templates/sada/ by
-- `pnpm --filter @workspace/store-sections template:sql sada 0090_library_templates_49_100.sql`.
-- Insert-only: Adds the template row (never
-- the default; the store keeps its own until the seller uses it) and its
-- version, only when the key is new.
-- An existing template (and its current version) is never changed.
--
-- Idempotent.

WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'sada',
    '{"ar":"صدى","en":"Sada"}'::jsonb,
    '{"ar":"محل صوتيات بواجهة داكنة: كلمة كبيرة، مقارنة سماعتين، اختيارنا، التقسيط وآراء المستمعين. أربع صفحات جاهزة.","en":"A dark audio store: one big word, two earbuds head to head, our pick, installments and listener reviews. Four ready pages."}'::jsonb,
    'electronics',
    560,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
