-- 0090_library_templates_49_100.sql (storefront templates, 2026-10-19)
--
-- Storefront template "Tany" v1, generated from
-- packages/store-sections/src/templates/tany/ by
-- `pnpm --filter @workspace/store-sections template:sql tany 0090_library_templates_49_100.sql`.
-- Insert-only: Adds the template row (never
-- the default; the store keeps its own until the seller uses it) and its
-- version, only when the key is new.
-- An existing template (and its current version) is never changed.
--
-- Idempotent.

WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'tany',
    '{"ar":"تاني","en":"Tany"}'::jsonb,
    '{"ar":"إلكترونيات مجددة: وفّر لحد ٤٠٪، بنجدد الجهاز إزاي، الضمان، افتح قبل ما تدفع وتتبع طلبك. أربع صفحات جاهزة.","en":"Refurbished electronics: save up to 40%, how we renew a device, warranty, open before you pay and order tracking. Four ready pages."}'::jsonb,
    'electronics',
    590,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
INSERT INTO template_versions (id, template_id, version, schema_version, config, changelog)
SELECT nt.current_version_id, nt.id, 1, 1,
