-- Storefront template "Kohl" v1, generated from
-- packages/store-sections/src/templates/kohl/ by
-- `pnpm --filter @workspace/store-sections template:sql kohl 0090_library_templates_49_100.sql`.
-- Insert-only: Adds the template row (never
-- the default; the store keeps its own until the seller uses it) and its
-- version, only when the key is new.
-- An existing template (and its current version) is never changed.
--
-- Idempotent.

WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'kohl',
    '{"ar":"كحل","en":"Kohl"}'::jsonb,
    '{"ar":"مكياج جريء: كلمة كبيرة، عرض الأسبوع، وفّري مع كل ما تزودي وادعي صاحبتك. أربع صفحات جاهزة.","en":"Bold makeup: a big word hero, this week''s deal, spend tiers and refer a friend. Four ready pages."}'::jsonb,
    'beauty',
    610,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
