--
-- Storefront template "Sabon" v1, generated from
-- packages/store-sections/src/templates/sabon/ by
-- `pnpm --filter @workspace/store-sections template:sql sabon 0090_library_templates_49_100.sql`.
-- Insert-only: Adds the template row (never
-- the default; the store keeps its own until the seller uses it) and its
-- version, only when the key is new.
-- An existing template (and its current version) is never changed.
--
-- Idempotent.

WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'sabon',
    '{"ar":"صابون","en":"Sabon"}'::jsonb,
    '{"ar":"صابون يدوي ومستلزمات حمام: ٤ قطع بسعر ٣، تسوق حسب الاستخدام، من الزيت للقالب وهدف التوصيل المجاني. أربع صفحات جاهزة.","en":"Handmade soap and bath: four bars for three, shop by use, from oil to bar and a free delivery goal. Four ready pages."}'::jsonb,
    'beauty',
    630,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
