-- Storefront template "Barber" v1, generated from
-- packages/store-sections/src/templates/barber/ by
-- `pnpm --filter @workspace/store-sections template:sql barber 0090_library_templates_49_100.sql`.
-- Insert-only: Adds the template row (never
-- the default; the store keeps its own until the seller uses it) and its
-- version, only when the key is new.
-- An existing template (and its current version) is never changed.
--
-- Idempotent.

WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'barber',
    '{"ar":"باربر","en":"Barber"}'::jsonb,
    '{"ar":"عناية رجالي: أسعار الكرسي، احجز معاد، طقم الدقن، الباربرز وآراء الزباين. أربع صفحات جاهزة.","en":"Men''s grooming: chair prices, booking, the beard kit, the barbers and regulars'' reviews. Four ready pages."}'::jsonb,
    'beauty',
    640,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
