-- `pnpm --filter @workspace/store-sections template:sql matbakh 0090_library_templates_49_100.sql`.
-- Insert-only: Adds the template row (never
-- the default; the store keeps its own until the seller uses it) and its
-- version, only when the key is new.
-- An existing template (and its current version) is never changed.
--
-- Idempotent.

WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'matbakh',
    '{"ar":"مطبخ","en":"Matbakh"}'::jsonb,
    '{"ar":"أساسيات مطبخ عصرية: بحث سريع، أقسام، شلف الأسبوع، على قد الميزانية وافتح قبل ما تدفع. أربع صفحات جاهزة.","en":"Modern kitchen basics: quick search, departments, this week''s shelf, a budget shelf and open before you pay. Four ready pages."}'::jsonb,
    'kitchen',
    650,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
