-- 0090_library_templates_49_100.sql (storefront templates, 2026-10-19)
--
-- Storefront template "Fokhar" v1, generated from
-- packages/store-sections/src/templates/fokhar/ by
-- `pnpm --filter @workspace/store-sections template:sql fokhar 0090_library_templates_49_100.sql`.
-- Insert-only: Adds the template row (never
-- the default; the store keeps its own until the seller uses it) and its
-- version, only when the key is new.
-- An existing template (and its current version) is never changed.
--
-- Idempotent.

WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'fokhar',
    '{"ar":"فخار","en":"Fokhar"}'::jsonb,
    '{"ar":"خزف يدوي: حرقة الأسبوع، من الطين للسفرة، الفخرانية وتغليف في علبتين. أربع صفحات جاهزة.","en":"Handmade ceramics: this week’s firing, clay to table, the potters and double-boxed delivery. Four ready pages."}'::jsonb,
    'handmade',
    660,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
