-- 0090_library_templates_49_100.sql (storefront templates, 2026-10-19)
--
-- Storefront template "Halawa" v1, generated from
-- packages/store-sections/src/templates/halawa/ by
-- `pnpm --filter @workspace/store-sections template:sql halawa 0090_library_templates_49_100.sql`.
-- Insert-only: Adds the template row (never
-- the default; the store keeps its own until the seller uses it) and its
-- version, only when the key is new.
-- An existing template (and its current version) is never changed.
--
-- Idempotent.

WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'halawa',
    '{"ar":"حلاوة","en":"Halawa"}'::jsonb,
    '{"ar":"حلويات شرقي: حملات الموسم، نفسك في إيه، هدايا لكل زيارة، الأكتر طلباً وحكاية ٥٠ سنة. أربع صفحات جاهزة.","en":"Oriental sweets: seasonal campaigns, what are you craving, gifts for every visit, the most ordered and fifty years of trays. Four ready pages."}'::jsonb,
    'sweets',
    720,
    false,
    true,
    false,
