-- `pnpm --filter @workspace/store-sections template:sql atara 0090_library_templates_49_100.sql`.
-- Insert-only: Adds the template row (never
-- the default; the store keeps its own until the seller uses it) and its
-- version, only when the key is new.
-- An existing template (and its current version) is never changed.
--
-- Idempotent.

WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'atara',
    '{"ar":"عطارة","en":"Atara"}'::jsonb,
    '{"ar":"توابل وأعشاب: بيتطحن طازة، طقم المطبخ، الأكتر إعادة طلب، كوبون أول طلب وآراء الجيران. أربع صفحات جاهزة.","en":"Spices and herbs: ground fresh, the kitchen set, the most reordered, a first-order coupon and the neighbours’ reviews. Four ready pages."}'::jsonb,
    'food',
    730,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
