--
-- Storefront template "Bunn" v1, generated from
-- packages/store-sections/src/templates/bunn/ by
-- `pnpm --filter @workspace/store-sections template:sql bunn 0090_library_templates_49_100.sql`.
-- Insert-only: Adds the template row (never
-- the default; the store keeps its own until the seller uses it) and its
-- version, only when the key is new.
-- An existing template (and its current version) is never changed.
--
-- Idempotent.

WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'bunn',
    '{"ar":"بُن","en":"Bunn"}'::jsonb,
    '{"ar":"اشتراك قهوة مختصة: كلمة تحميص الكبيرة، اشترك ووفّر، ابدأ من هنا، طريقة التحضير، نقط بن ورسايل الصبح. أربع صفحات جاهزة.","en":"Specialty coffee subscription: the big ROAST word, subscribe and save, start here, a brewing guide, Bunn points and morning messages. Four ready pages."}'::jsonb,
    'sweets',
    750,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
