-- 0090_library_templates_49_100.sql (storefront templates, 2026-10-19)
--
-- Storefront template "Nour" v1, generated from
-- packages/store-sections/src/templates/nour/ by
-- `pnpm --filter @workspace/store-sections template:sql nour 0090_library_templates_49_100.sql`.
-- Insert-only: Adds the template row (never
-- the default; the store keeps its own until the seller uses it) and its
-- version, only when the key is new.
-- An existing template (and its current version) is never changed.
--
-- Idempotent.

WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'nour',
    '{"ar":"نور","en":"Nour"}'::jsonb,
    '{"ar":"محل إضاءة بصفحة رئيسية غامقة: كلمة كبيرة، الأكتر نوراً، خدمة التركيب والتقسيط. أربع صفحات جاهزة.","en":"Lighting shop with a dark home page: one big word, most lit, installation services and instalments. Four ready pages."}'::jsonb,
    'home',
    780,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
