-- Storefront template "Mafrash" v1, generated from
-- packages/store-sections/src/templates/mafrash/ by
-- `pnpm --filter @workspace/store-sections template:sql mafrash 0090_library_templates_49_100.sql`.
-- Insert-only: Adds the template row (never
-- the default; the store keeps its own until the seller uses it) and its
-- version, only when the key is new.
-- An existing template (and its current version) is never changed.
--
-- Idempotent.

WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'mafrash',
    '{"ar":"مفرش","en":"Mafrash"}'::jsonb,
    '{"ar":"مفارش وملايات: تجربة ٣٠ ليلة، طقم السرير، قطن مصري، ألوان جديدة وشارك نومة حلوة. أربع صفحات جاهزة.","en":"Bedding and textiles: a 30-night trial, the bed set, Egyptian cotton, new colours and share a good night. Four ready pages."}'::jsonb,
    'home',
    790,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
