-- 0090_library_templates_49_100.sql (storefront templates, 2026-10-19)
--
-- Storefront template "Zahra" v1, generated from
-- packages/store-sections/src/templates/zahra/ by
-- `pnpm --filter @workspace/store-sections template:sql zahra 0090_library_templates_49_100.sql`.
-- Insert-only: Adds the template row (never
-- the default; the store keeps its own until the seller uses it) and its
-- version, only when the key is new.
-- An existing template (and its current version) is never changed.
--
-- Idempotent.

WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'zahra',
    '{"ar":"زهرة","en":"Zahra"}'::jsonb,
    '{"ar":"مجوهرات مطلية دهب يومية: هيرو بنتو، أقسام دائرية، هدايا حسب الميزانية، ادّي وخدي وآراء العميلات. أربع صفحات جاهزة.","en":"Everyday gold-plated jewellery: a bento hero, story rings, gifts by budget, refer a friend and reviews. Four ready pages."}'::jsonb,
    'jewelry',
    810,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
