--
-- Storefront template "Nuqra" v1, generated from
-- packages/store-sections/src/templates/nuqra/ by
-- `pnpm --filter @workspace/store-sections template:sql nuqra 0090_library_templates_49_100.sql`.
-- Insert-only: Adds the template row (never
-- the default; the store keeps its own until the seller uses it) and its
-- version, only when the key is new.
-- An existing template (and its current version) is never changed.
--
-- Idempotent.

WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'nuqra',
    '{"ar":"نقرة","en":"Nuqra"}'::jsonb,
    '{"ar":"فضة رجالي: بوستر بستيكر السعر، القطع الأساسية، خدمات بعد البيع، مقارنة ورسايل الواتساب. أربع صفحات جاهزة.","en":"Men''s silver: a poster with a price sticker, the core pieces, after-sale services, a comparison and WhatsApp reviews. Four ready pages."}'::jsonb,
    'jewelry',
    820,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
