-- 0090_library_templates_49_100.sql (storefront templates, 2026-10-19)
--
-- Storefront template "Saat" v1, generated from
-- packages/store-sections/src/templates/saat/ by
-- `pnpm --filter @workspace/store-sections template:sql saat 0090_library_templates_49_100.sql`.
-- Insert-only: Adds the template row (never
-- the default; the store keeps its own until the seller uses it) and its
-- version, only when the key is new.
-- An existing template (and its current version) is never changed.
--
-- Idempotent.

WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'saat',
    '{"ar":"ساعات","en":"Saat"}'::jsonb,
    '{"ar":"ساعات كلاسيك: هيرو نصين، عقارب ولا سمارت، التقسيط، أسعار الصيانة والفروع. أربع صفحات جاهزة.","en":"Classic watches: a split hero, analogue or smart, instalments, service prices and the shops. Four ready pages."}'::jsonb,
    'jewelry',
    840,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
