-- Storefront template "Mama" v1, generated from
-- packages/store-sections/src/templates/mama/ by
-- `pnpm --filter @workspace/store-sections template:sql mama 0090_library_templates_49_100.sql`.
-- Insert-only: Adds the template row (never
-- the default; the store keeps its own until the seller uses it) and its
-- version, only when the key is new.
-- An existing template (and its current version) is never changed.
--
-- Idempotent.

WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'mama',
    '{"ar":"ماما","en":"Mama"}'::jsonb,
    '{"ar":"مستلزمات بيبي هادية: حسب سن البيبي، شنطة الولادة، وعدنا وكارت هدية لمامي جديدة. أربع صفحات جاهزة.","en":"Calm baby essentials: shop by the baby’s age, a hospital bag, our promise and a gift card for a new mum. Four ready pages."}'::jsonb,
    'kids',
    870,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
