-- 0090_library_templates_49_100.sql (storefront templates, 2026-10-19)
--
-- Storefront template "Madrasa" v1, generated from
-- packages/store-sections/src/templates/madrasa/ by
-- `pnpm --filter @workspace/store-sections template:sql madrasa 0090_library_templates_49_100.sql`.
-- Insert-only: Adds the template row (never
-- the default; the store keeps its own until the seller uses it) and its
-- version, only when the key is new.
-- An existing template (and its current version) is never changed.
--
-- Idempotent.

WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'madrasa',
    '{"ar":"مدرسة","en":"Madrasa"}'::jsonb,
    '{"ar":"أدوات مدرسية: ابحث في اللستة، ابعت اللستة، في كل لستة وباكدج البداية. أربع صفحات جاهزة.","en":"School supplies: search the list, send your list, on every list and the starter pack. Four ready pages."}'::jsonb,
    'books',
    880,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
