--
-- Storefront template "Hikaya" v1, generated from
-- packages/store-sections/src/templates/hikaya/ by
-- `pnpm --filter @workspace/store-sections template:sql hikaya 0090_library_templates_49_100.sql`.
-- Insert-only: Adds the template row (never
-- the default; the store keeps its own until the seller uses it) and its
-- version, only when the key is new.
-- An existing template (and its current version) is never changed.
--
-- Idempotent.

WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'hikaya',
    '{"ar":"حكاية","en":"Hikaya"}'::jsonb,
    '{"ar":"نادي كتب أطفال: بوكس الشهر، بيحبوا إيه، الاشتراك، نقط القراية ورف الكتب. أربع صفحات جاهزة.","en":"A kids’ book club: this month’s box, what they love, subscribe, reading points and the shelf. Four ready pages."}'::jsonb,
    'books',
    890,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
