WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'boxing',
    '{"ar":"لكمة","en":"Lakma"}'::jsonb,
    '{"ar":"ملاكمة وقتال بصفحة رئيسية غامقة: خصم الباكدجات، الأكتر استخداماً، باكدج أول أسبوع ولكمة في أرقام. أربع صفحات جاهزة.","en":"Boxing and combat with a dark homepage: kit offer, most used, the week-one kit and Lakma in numbers. Four ready pages."}'::jsonb,
    'sports',
    950,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
