--
-- Storefront template "Kawetch" v1, generated from
-- packages/store-sections/src/templates/tyre/ by
-- `pnpm --filter @workspace/store-sections template:sql tyre 0090_library_templates_49_100.sql`.
-- Insert-only: Adds the template row (never
-- the default; the store keeps its own until the seller uses it) and its
-- version, only when the key is new.
-- An existing template (and its current version) is never changed.
--
-- Idempotent.

WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'tyre',
    '{"ar":"كاوتش","en":"Kawetch"}'::jsonb,
    '{"ar":"كاوتش وتركيب: بحث بالمقاس، تركيب في البيت، حجز معاد، تقسيط ومساعدة في المقاس. أربع صفحات جاهزة.","en":"Tyres and fitting: search by size, home fitting, booking, instalments and help with sizes. Four ready pages."}'::jsonb,
    'auto',
    960,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
INSERT INTO template_versions (id, template_id, version, schema_version, config, changelog)
